public void callAPI()
{
    Map configMap = new Map(Types::String, Types::String);
    configMap.insert('<DataAreaId>', curExt());
    configMap.insert('<netArea>', curExt());
    this.prepareBody(configMap);
    this.sendPostRequest();
    EGS_API_DataContract_Response_Installation res = FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response_Installation), responseText);
    this.log("InstNum", res.parmInstallationNum());
}
